window.AP_CHEMISTRY_DECKS = [{"id":"apchem-unit-1","name":"AP Chemistry · Unit 1","shortName":"Unit 1: Atomic Structure and Properties","builtIn":true,"sourceTitle":"AP Chemistry Course and Exam Description, Effective Fall 2024","sourceUrl":"https://apcentral.collegeboard.org/media/pdf/ap-chemistry-course-and-exam-description.pdf","cards":[{"id":"apchem-u1-c1","front":"atom","back":"The smallest unit of an element that retains the element's chemical identity."},{"id":"apchem-u1-c2","front":"proton","back":"A positively charged subatomic particle in the nucleus; its number determines the element."},{"id":"apchem-u1-c3","front":"neutron","back":"An electrically neutral subatomic particle in the nucleus that contributes to atomic mass."},{"id":"apchem-u1-c4","front":"electron","back":"A negatively charged subatomic particle found in quantized energy levels outside the nucleus."},{"id":"apchem-u1-c5","front":"atomic number","back":"The number of protons in an atom's nucleus."},{"id":"apchem-u1-c6","front":"mass number","back":"The total number of protons and neutrons in one isotope."},{"id":"apchem-u1-c7","front":"isotope","back":"An atom of an element with the same number of protons but a different number of neutrons."},{"id":"apchem-u1-c8","front":"average atomic mass","back":"The weighted mean of an element's naturally occurring isotope masses."},{"id":"apchem-u1-c9","front":"mole","back":"An amount containing exactly 6.02214076 × 10²³ representative particles."},{"id":"apchem-u1-c10","front":"Avogadro's number","back":"The number of representative particles in one mole: 6.02214076 × 10²³ mol⁻¹."},{"id":"apchem-u1-c11","front":"molar mass","back":"The mass in grams of one mole of a substance."},{"id":"apchem-u1-c12","front":"mass spectrum","back":"A plot of ion abundance versus mass-to-charge ratio used to identify isotopes or molecular fragments."},{"id":"apchem-u1-c13","front":"electromagnetic radiation","back":"Energy that travels through space as oscillating electric and magnetic fields."},{"id":"apchem-u1-c14","front":"photon","back":"A quantum of electromagnetic radiation with energy E = hν."},{"id":"apchem-u1-c15","front":"ground state","back":"The lowest-energy electron configuration of an atom or ion."},{"id":"apchem-u1-c16","front":"excited state","back":"A state in which one or more electrons occupy higher-energy levels than in the ground state."},{"id":"apchem-u1-c17","front":"orbital","back":"A mathematical description of a region in which an electron has a high probability of being found."},{"id":"apchem-u1-c18","front":"electron configuration","back":"A notation showing how electrons are distributed among an atom's orbitals."},{"id":"apchem-u1-c19","front":"Aufbau principle","back":"Electrons occupy the lowest-energy available orbitals before higher-energy orbitals."},{"id":"apchem-u1-c20","front":"Pauli exclusion principle","back":"No two electrons in an atom can have the same set of four quantum numbers; an orbital holds at most two electrons with opposite spins."},{"id":"apchem-u1-c21","front":"Hund's rule","back":"Electrons occupy equal-energy orbitals singly with parallel spins before pairing."},{"id":"apchem-u1-c22","front":"valence electrons","back":"Electrons in an atom's highest occupied principal energy level that participate most directly in bonding."},{"id":"apchem-u1-c23","front":"core electrons","back":"Inner-shell electrons that generally do not participate directly in bonding."},{"id":"apchem-u1-c24","front":"photoelectron spectroscopy","back":"A technique that measures electron binding energies by ejecting electrons with photons."},{"id":"apchem-u1-c25","front":"Coulomb's law","back":"The electrostatic attraction or repulsion between charges increases with charge magnitude and decreases with the square of separation."},{"id":"apchem-u1-c26","front":"effective nuclear charge","back":"The net positive charge experienced by a valence electron after shielding by other electrons."},{"id":"apchem-u1-c27","front":"shielding","back":"Reduction of nuclear attraction for outer electrons caused by repulsion from inner electrons."},{"id":"apchem-u1-c28","front":"atomic radius","back":"A measure of atomic size that generally decreases across a period and increases down a group."},{"id":"apchem-u1-c29","front":"ionization energy","back":"The energy required to remove an electron from a gaseous atom or ion."},{"id":"apchem-u1-c30","front":"electron affinity","back":"The energy change when a gaseous atom gains an electron."},{"id":"apchem-u1-c31","front":"ionic radius","back":"The size of an ion; cations are usually smaller and anions larger than their neutral atoms."},{"id":"apchem-u1-c32","front":"periodic law","back":"Element properties recur periodically when elements are arranged by atomic number."},{"id":"apchem-u1-eq1","front":"Photon energy","back":"Use to calculate the energy of a photon from its frequency.","backImage":"./ap-chemistry-images/unit-1-formula-1.svg"},{"id":"apchem-u1-eq2","front":"Wave relationship","back":"Use to relate the wavelength and frequency of electromagnetic radiation.","backImage":"./ap-chemistry-images/unit-1-formula-2.svg"},{"id":"apchem-u1-eq3","front":"Coulombic force","back":"Use qualitatively to compare attraction or repulsion as charge and separation change.","backImage":"./ap-chemistry-images/unit-1-formula-3.svg"},{"id":"apchem-u1-eq4","front":"Moles from mass","back":"Use to convert a sample mass to moles using molar mass.","backImage":"./ap-chemistry-images/unit-1-formula-4.svg"}],"questions":[],"feynmanPrompts":[{"id":"apchem-u1-f1","prompt":"Atomic structure and isotope abundance"},{"id":"apchem-u1-f2","prompt":"Electron configurations and periodic trends"},{"id":"apchem-u1-f3","prompt":"Photoelectron spectroscopy and electron binding energy"}]},{"id":"apchem-unit-2","name":"AP Chemistry · Unit 2","shortName":"Unit 2: Compound Structure and Properties","builtIn":true,"sourceTitle":"AP Chemistry Course and Exam Description, Effective Fall 2024","sourceUrl":"https://apcentral.collegeboard.org/media/pdf/ap-chemistry-course-and-exam-description.pdf","cards":[{"id":"apchem-u2-c1","front":"chemical bond","back":"An electrostatic attraction that holds atoms or ions together."},{"id":"apchem-u2-c2","front":"ionic bond","back":"Electrostatic attraction between oppositely charged ions."},{"id":"apchem-u2-c3","front":"covalent bond","back":"A bond formed when atoms share one or more pairs of electrons."},{"id":"apchem-u2-c4","front":"metallic bonding","back":"Attraction between metal cations and a mobile sea of delocalized valence electrons."},{"id":"apchem-u2-c5","front":"electronegativity","back":"An atom's ability to attract shared electrons in a bond."},{"id":"apchem-u2-c6","front":"bond polarity","back":"Unequal sharing of bonding electrons caused by an electronegativity difference."},{"id":"apchem-u2-c7","front":"dipole moment","back":"A measure of charge separation in a bond or molecule."},{"id":"apchem-u2-c8","front":"Lewis diagram","back":"A representation of valence electrons, bonds, and lone pairs in a molecule or ion."},{"id":"apchem-u2-c9","front":"octet rule","back":"The tendency of many main-group atoms to form bonds that give them eight valence electrons."},{"id":"apchem-u2-c10","front":"formal charge","back":"The charge assigned to an atom in a Lewis structure by dividing bonding electrons equally."},{"id":"apchem-u2-c11","front":"resonance","back":"Use of two or more valid Lewis structures to represent electron delocalization in one species."},{"id":"apchem-u2-c12","front":"bond order","back":"The number of shared electron pairs between two atoms; higher bond order generally means a shorter, stronger bond."},{"id":"apchem-u2-c13","front":"bond length","back":"The equilibrium distance between bonded nuclei."},{"id":"apchem-u2-c14","front":"bond energy","back":"The energy required to break one mole of a specified gaseous bond."},{"id":"apchem-u2-c15","front":"VSEPR theory","back":"A model predicting molecular geometry by minimizing repulsions among electron domains around a central atom."},{"id":"apchem-u2-c16","front":"electron-domain geometry","back":"The arrangement of all bonding regions and lone pairs around a central atom."},{"id":"apchem-u2-c17","front":"molecular geometry","back":"The three-dimensional arrangement of atoms in a molecule, excluding lone pairs from the named shape."},{"id":"apchem-u2-c18","front":"linear geometry","back":"A two-domain arrangement with a 180° bond angle."},{"id":"apchem-u2-c19","front":"trigonal planar geometry","back":"A three-domain arrangement with approximately 120° bond angles."},{"id":"apchem-u2-c20","front":"tetrahedral geometry","back":"A four-domain arrangement with approximately 109.5° bond angles."},{"id":"apchem-u2-c21","front":"trigonal bipyramidal geometry","back":"A five-domain arrangement with equatorial and axial positions."},{"id":"apchem-u2-c22","front":"octahedral geometry","back":"A six-domain arrangement with 90° angles."},{"id":"apchem-u2-c23","front":"hybridization","back":"A bonding model that combines atomic orbitals into equivalent hybrid orbitals."},{"id":"apchem-u2-c24","front":"sigma bond","back":"A bond formed by head-on orbital overlap along the internuclear axis."},{"id":"apchem-u2-c25","front":"pi bond","back":"A bond formed by sideways overlap of parallel orbitals above and below the internuclear axis."},{"id":"apchem-u2-c26","front":"molecular polarity","back":"Net charge separation determined by both bond polarities and molecular geometry."},{"id":"apchem-u2-c27","front":"lattice energy","back":"The energy associated with separating an ionic solid into gaseous ions; its magnitude grows with ionic charge and decreases with ion size."},{"id":"apchem-u2-c28","front":"alloy","back":"A metallic material containing more than one element."},{"id":"apchem-u2-eq1","front":"Formal charge","back":"Use to evaluate atoms in Lewis structures and compare resonance contributors.","backImage":"./ap-chemistry-images/unit-2-formula-1.svg"},{"id":"apchem-u2-eq2","front":"Bond enthalpy estimate","back":"Use average bond enthalpies to estimate reaction enthalpy.","backImage":"./ap-chemistry-images/unit-2-formula-2.svg"}],"questions":[],"feynmanPrompts":[{"id":"apchem-u2-f1","prompt":"Lewis structures, formal charge, and resonance"},{"id":"apchem-u2-f2","prompt":"VSEPR geometry and molecular polarity"},{"id":"apchem-u2-f3","prompt":"Ionic, covalent, and metallic bonding"}]},{"id":"apchem-unit-3","name":"AP Chemistry · Unit 3","shortName":"Unit 3: Properties of Substances and Mixtures","builtIn":true,"sourceTitle":"AP Chemistry Course and Exam Description, Effective Fall 2024","sourceUrl":"https://apcentral.collegeboard.org/media/pdf/ap-chemistry-course-and-exam-description.pdf","cards":[{"id":"apchem-u3-c1","front":"intermolecular force","back":"An attraction between separate particles that influences physical properties."},{"id":"apchem-u3-c2","front":"London dispersion force","back":"An attraction caused by instantaneous and induced dipoles; it occurs in all particles."},{"id":"apchem-u3-c3","front":"dipole-dipole force","back":"An attraction between permanent partial charges of polar molecules."},{"id":"apchem-u3-c4","front":"hydrogen bonding","back":"A strong dipole-dipole attraction involving H bonded to N, O, or F and a lone pair on N, O, or F."},{"id":"apchem-u3-c5","front":"ion-dipole force","back":"An attraction between an ion and the partial charges of a polar molecule."},{"id":"apchem-u3-c6","front":"polarizability","back":"The ease with which a particle's electron cloud can be distorted."},{"id":"apchem-u3-c7","front":"vapor pressure","back":"The pressure exerted by a vapor in dynamic equilibrium with its liquid or solid."},{"id":"apchem-u3-c8","front":"boiling point","back":"The temperature at which a liquid's vapor pressure equals the external pressure."},{"id":"apchem-u3-c9","front":"surface tension","back":"The energy required to increase a liquid's surface area, arising from cohesive forces."},{"id":"apchem-u3-c10","front":"viscosity","back":"A fluid's resistance to flow."},{"id":"apchem-u3-c11","front":"crystalline solid","back":"A solid whose particles occupy a repeating, ordered structure."},{"id":"apchem-u3-c12","front":"amorphous solid","back":"A solid lacking long-range repeating order."},{"id":"apchem-u3-c13","front":"unit cell","back":"The smallest repeating structural unit of a crystal lattice."},{"id":"apchem-u3-c14","front":"solution","back":"A homogeneous mixture of solute particles dispersed in a solvent."},{"id":"apchem-u3-c15","front":"solute","back":"The component of a solution present in the smaller amount or dissolved by the solvent."},{"id":"apchem-u3-c16","front":"solvent","back":"The component that forms the medium in which a solute is dispersed."},{"id":"apchem-u3-c17","front":"molarity","back":"Moles of solute per liter of solution."},{"id":"apchem-u3-c18","front":"dilution","back":"Lowering a solution's concentration by adding solvent while conserving moles of solute."},{"id":"apchem-u3-c19","front":"electrolyte","back":"A substance that produces mobile ions when dissolved or molten and therefore conducts electricity."},{"id":"apchem-u3-c20","front":"strong electrolyte","back":"A soluble ionic compound or strong acid/base that forms ions essentially completely in solution."},{"id":"apchem-u3-c21","front":"solubility","back":"The maximum amount of solute that dissolves under specified conditions."},{"id":"apchem-u3-c22","front":"like dissolves like","back":"A guideline that substances dissolve best in solvents with similar intermolecular-force characteristics."},{"id":"apchem-u3-c23","front":"chromatography","back":"A separation technique based on differing attractions for stationary and mobile phases."},{"id":"apchem-u3-c24","front":"Beer-Lambert law","back":"The linear relationship A = εbc connecting absorbance, concentration, path length, and molar absorptivity."},{"id":"apchem-u3-c25","front":"ideal gas","back":"A model gas with negligible particle volume and no intermolecular attractions."},{"id":"apchem-u3-c26","front":"kinetic molecular theory","back":"A model relating gas pressure and temperature to constant random particle motion and elastic collisions."},{"id":"apchem-u3-c27","front":"partial pressure","back":"The pressure a component gas would exert alone in the same volume and temperature."},{"id":"apchem-u3-c28","front":"mole fraction","back":"The fraction of all gas particles belonging to one component."},{"id":"apchem-u3-c29","front":"deviation from ideal behavior","back":"Behavior caused mainly by intermolecular attractions at low temperature or finite molecular volume at high pressure."},{"id":"apchem-u3-eq1","front":"Ideal gas law","back":"Use to relate pressure, volume, amount, and absolute temperature for an approximately ideal gas.","backImage":"./ap-chemistry-images/unit-3-formula-1.svg"},{"id":"apchem-u3-eq2","front":"Combined gas law","back":"Use for a fixed amount of gas changing pressure, volume, and temperature.","backImage":"./ap-chemistry-images/unit-3-formula-2.svg"},{"id":"apchem-u3-eq3","front":"Dalton's law","back":"Use to find the total pressure of a gas mixture.","backImage":"./ap-chemistry-images/unit-3-formula-3.svg"},{"id":"apchem-u3-eq4","front":"Partial pressure","back":"Use mole fraction to find a component's pressure in an ideal-gas mixture.","backImage":"./ap-chemistry-images/unit-3-formula-4.svg"},{"id":"apchem-u3-eq5","front":"Molarity","back":"Use to express solution concentration in moles per liter.","backImage":"./ap-chemistry-images/unit-3-formula-5.svg"},{"id":"apchem-u3-eq6","front":"Dilution equation","back":"Use when solvent is added and the moles of solute remain constant.","backImage":"./ap-chemistry-images/unit-3-formula-6.svg"},{"id":"apchem-u3-eq7","front":"Beer-Lambert law","back":"Use absorbance to determine concentration or relate absorbance to path length.","backImage":"./ap-chemistry-images/unit-3-formula-7.svg"},{"id":"apchem-u3-eq8","front":"Density","back":"Use to relate a sample's mass and volume.","backImage":"./ap-chemistry-images/unit-3-formula-8.svg"}],"questions":[],"feynmanPrompts":[{"id":"apchem-u3-f1","prompt":"Intermolecular forces and physical properties"},{"id":"apchem-u3-f2","prompt":"Solutions, solubility, and separation"},{"id":"apchem-u3-f3","prompt":"Gas behavior and kinetic molecular theory"}]},{"id":"apchem-unit-4","name":"AP Chemistry · Unit 4","shortName":"Unit 4: Chemical Reactions","builtIn":true,"sourceTitle":"AP Chemistry Course and Exam Description, Effective Fall 2024","sourceUrl":"https://apcentral.collegeboard.org/media/pdf/ap-chemistry-course-and-exam-description.pdf","cards":[{"id":"apchem-u4-c1","front":"chemical equation","back":"A symbolic representation of reactants, products, physical states, and stoichiometric relationships."},{"id":"apchem-u4-c2","front":"balanced equation","back":"An equation with equal numbers of each type of atom and equal net charge on both sides."},{"id":"apchem-u4-c3","front":"net ionic equation","back":"An equation showing only species that undergo chemical change in aqueous solution."},{"id":"apchem-u4-c4","front":"spectator ion","back":"An ion present in solution that does not participate in the net chemical change."},{"id":"apchem-u4-c5","front":"precipitation reaction","back":"A reaction in which dissolved ions form an insoluble solid."},{"id":"apchem-u4-c6","front":"acid-base reaction","back":"A reaction involving proton transfer or neutralization."},{"id":"apchem-u4-c7","front":"oxidation-reduction reaction","back":"A reaction involving electron transfer and changes in oxidation number."},{"id":"apchem-u4-c8","front":"oxidation","back":"Loss of electrons or an increase in oxidation number."},{"id":"apchem-u4-c9","front":"reduction","back":"Gain of electrons or a decrease in oxidation number."},{"id":"apchem-u4-c10","front":"oxidizing agent","back":"A reactant that accepts electrons and is reduced."},{"id":"apchem-u4-c11","front":"reducing agent","back":"A reactant that donates electrons and is oxidized."},{"id":"apchem-u4-c12","front":"oxidation number","back":"A bookkeeping charge assigned using agreed rules to track electron transfer."},{"id":"apchem-u4-c13","front":"stoichiometry","back":"Quantitative relationships among reactants and products based on a balanced equation."},{"id":"apchem-u4-c14","front":"limiting reactant","back":"The reactant consumed first, thereby limiting the maximum amount of product."},{"id":"apchem-u4-c15","front":"excess reactant","back":"A reactant remaining after the limiting reactant is consumed."},{"id":"apchem-u4-c16","front":"theoretical yield","back":"The maximum product predicted from stoichiometry and the limiting reactant."},{"id":"apchem-u4-c17","front":"actual yield","back":"The amount of product actually obtained experimentally."},{"id":"apchem-u4-c18","front":"percent yield","back":"Actual yield divided by theoretical yield, multiplied by 100%."},{"id":"apchem-u4-c19","front":"titration","back":"A quantitative procedure in which a solution of known concentration reacts with an analyte to determine its amount."},{"id":"apchem-u4-c20","front":"equivalence point","back":"The point at which titrant and analyte have reacted in the exact stoichiometric ratio."},{"id":"apchem-u4-c21","front":"endpoint","back":"The observed signal used to approximate a titration's equivalence point."},{"id":"apchem-u4-c22","front":"gravimetric analysis","back":"Quantitative analysis based on measuring mass, often after forming and isolating a precipitate."},{"id":"apchem-u4-c23","front":"combustion analysis","back":"Determination of elemental composition by measuring combustion products such as CO₂ and H₂O."},{"id":"apchem-u4-eq1","front":"Percent yield","back":"Use to compare the experimentally obtained amount with the stoichiometric maximum.","backImage":"./ap-chemistry-images/unit-4-formula-1.svg"},{"id":"apchem-u4-eq2","front":"Titration stoichiometry","back":"Use the balanced reaction and moles n = MV to relate titrant and analyte at equivalence.","backImage":"./ap-chemistry-images/unit-4-formula-2.svg"}],"questions":[],"feynmanPrompts":[{"id":"apchem-u4-f1","prompt":"Writing net ionic equations"},{"id":"apchem-u4-f2","prompt":"Stoichiometry and limiting reactants"},{"id":"apchem-u4-f3","prompt":"Redox reactions and oxidation numbers"}]},{"id":"apchem-unit-5","name":"AP Chemistry · Unit 5","shortName":"Unit 5: Kinetics","builtIn":true,"sourceTitle":"AP Chemistry Course and Exam Description, Effective Fall 2024","sourceUrl":"https://apcentral.collegeboard.org/media/pdf/ap-chemistry-course-and-exam-description.pdf","cards":[{"id":"apchem-u5-c1","front":"reaction rate","back":"The change in concentration of a reactant or product per unit time."},{"id":"apchem-u5-c2","front":"rate law","back":"An experimentally determined equation relating reaction rate to reactant concentrations."},{"id":"apchem-u5-c3","front":"rate constant","back":"The proportionality constant k in a rate law; its value depends on temperature and the reaction."},{"id":"apchem-u5-c4","front":"reaction order","back":"An exponent in a rate law describing how rate responds to a reactant's concentration."},{"id":"apchem-u5-c5","front":"overall reaction order","back":"The sum of the concentration exponents in a rate law."},{"id":"apchem-u5-c6","front":"initial-rates method","back":"A method for determining reaction orders by comparing rates from experiments with different initial concentrations."},{"id":"apchem-u5-c7","front":"integrated rate law","back":"An equation relating reactant concentration to time for a specified reaction order."},{"id":"apchem-u5-c8","front":"half-life","back":"The time required for a reactant concentration to decrease to half its value."},{"id":"apchem-u5-c9","front":"elementary reaction","back":"A single molecular event whose stoichiometry can determine its rate law."},{"id":"apchem-u5-c10","front":"reaction mechanism","back":"A sequence of elementary reactions whose sum is the overall reaction."},{"id":"apchem-u5-c11","front":"intermediate","back":"A species produced in one mechanism step and consumed in a later step."},{"id":"apchem-u5-c12","front":"rate-determining step","back":"A comparatively slow elementary step that constrains the overall rate."},{"id":"apchem-u5-c13","front":"molecularity","back":"The number of reacting particles involved in an elementary step."},{"id":"apchem-u5-c14","front":"collision model","back":"A model stating that reactions require collisions with sufficient energy and suitable orientation."},{"id":"apchem-u5-c15","front":"activation energy","back":"The minimum energy barrier that reacting particles must overcome."},{"id":"apchem-u5-c16","front":"transition state","back":"A high-energy, unstable arrangement at the top of the reaction-energy barrier."},{"id":"apchem-u5-c17","front":"catalyst","back":"A substance that increases reaction rate by providing a lower-activation-energy pathway and is regenerated."},{"id":"apchem-u5-c18","front":"homogeneous catalyst","back":"A catalyst in the same phase as the reactants."},{"id":"apchem-u5-c19","front":"heterogeneous catalyst","back":"A catalyst in a different phase, often acting at a surface."},{"id":"apchem-u5-c20","front":"Arrhenius equation","back":"An equation relating the rate constant to activation energy and absolute temperature."},{"id":"apchem-u5-eq1","front":"Zero-order integrated rate law","back":"Use when rate is independent of reactant concentration.","backImage":"./ap-chemistry-images/unit-5-formula-1.svg"},{"id":"apchem-u5-eq2","front":"First-order integrated rate law","back":"Use when a plot of ln[A] versus time is linear.","backImage":"./ap-chemistry-images/unit-5-formula-2.svg"},{"id":"apchem-u5-eq3","front":"Second-order integrated rate law","back":"Use when a plot of 1/[A] versus time is linear.","backImage":"./ap-chemistry-images/unit-5-formula-3.svg"},{"id":"apchem-u5-eq4","front":"First-order half-life","back":"Use to find the concentration-independent half-life of a first-order process.","backImage":"./ap-chemistry-images/unit-5-formula-4.svg"},{"id":"apchem-u5-eq5","front":"Arrhenius equation","back":"Use to relate a rate constant to temperature and activation energy.","backImage":"./ap-chemistry-images/unit-5-formula-5.svg"}],"questions":[],"feynmanPrompts":[{"id":"apchem-u5-f1","prompt":"Rate laws and reaction order"},{"id":"apchem-u5-f2","prompt":"Reaction mechanisms and rate-determining steps"},{"id":"apchem-u5-f3","prompt":"Activation energy and catalysis"}]},{"id":"apchem-unit-6","name":"AP Chemistry · Unit 6","shortName":"Unit 6: Thermochemistry","builtIn":true,"sourceTitle":"AP Chemistry Course and Exam Description, Effective Fall 2024","sourceUrl":"https://apcentral.collegeboard.org/media/pdf/ap-chemistry-course-and-exam-description.pdf","cards":[{"id":"apchem-u6-c1","front":"system","back":"The part of the universe selected for study."},{"id":"apchem-u6-c2","front":"surroundings","back":"Everything outside the system that can exchange energy or matter with it."},{"id":"apchem-u6-c3","front":"endothermic process","back":"A process in which the system absorbs heat from the surroundings."},{"id":"apchem-u6-c4","front":"exothermic process","back":"A process in which the system releases heat to the surroundings."},{"id":"apchem-u6-c5","front":"temperature","back":"A measure proportional to the average kinetic energy of particles."},{"id":"apchem-u6-c6","front":"heat","back":"Energy transferred because of a temperature difference."},{"id":"apchem-u6-c7","front":"thermal equilibrium","back":"The state reached when objects in contact have the same temperature and no net heat flows."},{"id":"apchem-u6-c8","front":"specific heat capacity","back":"The heat required to raise one gram of a substance by one kelvin or degree Celsius."},{"id":"apchem-u6-c9","front":"calorimetry","back":"Measurement of heat transferred during a physical or chemical process."},{"id":"apchem-u6-c10","front":"enthalpy","back":"A state function H whose change at constant pressure equals heat transferred for many chemical processes."},{"id":"apchem-u6-c11","front":"enthalpy of reaction","back":"The enthalpy change associated with a reaction as written."},{"id":"apchem-u6-c12","front":"standard enthalpy of formation","back":"The enthalpy change when one mole of a compound forms from its elements in their standard states."},{"id":"apchem-u6-c13","front":"Hess's law","back":"Because enthalpy is a state function, reaction enthalpies add when equations are added."},{"id":"apchem-u6-c14","front":"bond enthalpy","back":"The average energy required to break one mole of a specified gaseous bond."},{"id":"apchem-u6-c15","front":"state function","back":"A property determined only by the system's current state, not the path taken."},{"id":"apchem-u6-c16","front":"energy conservation","back":"Energy is transferred or transformed but the total energy of the universe remains constant."},{"id":"apchem-u6-c17","front":"coffee-cup calorimeter","back":"A constant-pressure calorimeter commonly used for reactions in solution."},{"id":"apchem-u6-c18","front":"bomb calorimeter","back":"A rigid constant-volume calorimeter commonly used for combustion reactions."},{"id":"apchem-u6-c19","front":"heating curve","back":"A graph of temperature versus added heat showing warming regions and phase-change plateaus."},{"id":"apchem-u6-c20","front":"phase change","back":"A physical transition between solid, liquid, and gas involving energy but no change in chemical identity."},{"id":"apchem-u6-eq1","front":"Calorimetry","back":"Use to calculate heat from mass, specific heat capacity, and temperature change.","backImage":"./ap-chemistry-images/unit-6-formula-1.svg"},{"id":"apchem-u6-eq2","front":"Heat balance","back":"Use in an isolated calorimeter: heat lost by one part equals heat gained by another.","backImage":"./ap-chemistry-images/unit-6-formula-2.svg"},{"id":"apchem-u6-eq3","front":"Formation enthalpies","back":"Use tabulated standard formation enthalpies to calculate a standard reaction enthalpy.","backImage":"./ap-chemistry-images/unit-6-formula-3.svg"},{"id":"apchem-u6-eq4","front":"Hess's law","back":"Use when target reaction equations can be constructed by adding known equations.","backImage":"./ap-chemistry-images/unit-6-formula-4.svg"}],"questions":[],"feynmanPrompts":[{"id":"apchem-u6-f1","prompt":"Calorimetry and energy transfer"},{"id":"apchem-u6-f2","prompt":"Reaction enthalpy and Hess's law"}]},{"id":"apchem-unit-7","name":"AP Chemistry · Unit 7","shortName":"Unit 7: Equilibrium","builtIn":true,"sourceTitle":"AP Chemistry Course and Exam Description, Effective Fall 2024","sourceUrl":"https://apcentral.collegeboard.org/media/pdf/ap-chemistry-course-and-exam-description.pdf","cards":[{"id":"apchem-u7-c1","front":"dynamic equilibrium","back":"A state in which forward and reverse reactions continue at equal rates, keeping concentrations constant."},{"id":"apchem-u7-c2","front":"equilibrium constant","back":"A ratio of product and reactant activities at equilibrium, each raised to its stoichiometric power."},{"id":"apchem-u7-c3","front":"law of mass action","back":"The rule used to construct an equilibrium expression from a balanced reaction."},{"id":"apchem-u7-c4","front":"reaction quotient","back":"A product-to-reactant ratio with the form of K, evaluated at any moment."},{"id":"apchem-u7-c5","front":"homogeneous equilibrium","back":"An equilibrium in which all reactants and products are in the same phase."},{"id":"apchem-u7-c6","front":"heterogeneous equilibrium","back":"An equilibrium involving more than one phase; pure solids and liquids are omitted from K."},{"id":"apchem-u7-c7","front":"Le Châtelier's principle","back":"An equilibrium system shifts in the direction that partially counteracts an imposed disturbance."},{"id":"apchem-u7-c8","front":"equilibrium shift","back":"A change in relative amounts of reactants and products as a system establishes a new equilibrium."},{"id":"apchem-u7-c9","front":"Kc","back":"An equilibrium constant expressed using molar concentrations."},{"id":"apchem-u7-c10","front":"Kp","back":"An equilibrium constant expressed using partial pressures of gases."},{"id":"apchem-u7-c11","front":"solubility product constant","back":"The equilibrium constant Ksp for dissolution of a sparingly soluble ionic solid."},{"id":"apchem-u7-c12","front":"common-ion effect","back":"Suppression of ionization or solubility caused by adding a species already present in the equilibrium."},{"id":"apchem-u7-c13","front":"coupled equilibrium","back":"Two or more equilibria sharing species, so one reaction influences the position of another."},{"id":"apchem-u7-c14","front":"large equilibrium constant","back":"A K much greater than 1 indicates products predominate at equilibrium."},{"id":"apchem-u7-c15","front":"small equilibrium constant","back":"A K much less than 1 indicates reactants predominate at equilibrium."},{"id":"apchem-u7-c16","front":"Q compared with K","back":"If Q < K the reaction proceeds forward; if Q > K it proceeds in reverse until equilibrium is reached."},{"id":"apchem-u7-c17","front":"equilibrium and catalysts","back":"A catalyst accelerates forward and reverse reactions equally, reducing time to equilibrium without changing K."},{"id":"apchem-u7-eq1","front":"Equilibrium constant","back":"Use equilibrium concentrations for aA + bB ⇌ cC + dD; omit pure solids and liquids.","backImage":"./ap-chemistry-images/unit-7-formula-1.svg"},{"id":"apchem-u7-eq2","front":"Reaction quotient","back":"Use current concentrations or pressures to predict the direction of net change by comparing Q with K.","backImage":"./ap-chemistry-images/unit-7-formula-2.svg"},{"id":"apchem-u7-eq3","front":"Solubility product","back":"Use ion concentrations at equilibrium for a sparingly soluble ionic solid.","backImage":"./ap-chemistry-images/unit-7-formula-3.svg"}],"questions":[],"feynmanPrompts":[{"id":"apchem-u7-f1","prompt":"Dynamic equilibrium and equilibrium constants"},{"id":"apchem-u7-f2","prompt":"Reaction quotient and predicting shifts"},{"id":"apchem-u7-f3","prompt":"Le Châtelier's principle and coupled equilibria"}]},{"id":"apchem-unit-8","name":"AP Chemistry · Unit 8","shortName":"Unit 8: Acids and Bases","builtIn":true,"sourceTitle":"AP Chemistry Course and Exam Description, Effective Fall 2024","sourceUrl":"https://apcentral.collegeboard.org/media/pdf/ap-chemistry-course-and-exam-description.pdf","cards":[{"id":"apchem-u8-c1","front":"Arrhenius acid","back":"A substance that increases hydronium concentration in water."},{"id":"apchem-u8-c2","front":"Arrhenius base","back":"A substance that increases hydroxide concentration in water."},{"id":"apchem-u8-c3","front":"Brønsted-Lowry acid","back":"A proton donor."},{"id":"apchem-u8-c4","front":"Brønsted-Lowry base","back":"A proton acceptor."},{"id":"apchem-u8-c5","front":"conjugate acid-base pair","back":"Two species differing by one proton."},{"id":"apchem-u8-c6","front":"amphiprotic species","back":"A species capable of either donating or accepting a proton."},{"id":"apchem-u8-c7","front":"strong acid","back":"An acid that ionizes essentially completely in water."},{"id":"apchem-u8-c8","front":"weak acid","back":"An acid that ionizes only partially in water."},{"id":"apchem-u8-c9","front":"strong base","back":"A base that dissociates or reacts essentially completely to produce hydroxide in water."},{"id":"apchem-u8-c10","front":"weak base","back":"A base that reacts only partially with water to produce its conjugate acid and hydroxide."},{"id":"apchem-u8-c11","front":"acid-ionization constant","back":"The equilibrium constant Ka for a weak acid's reaction with water."},{"id":"apchem-u8-c12","front":"base-ionization constant","back":"The equilibrium constant Kb for a weak base's reaction with water."},{"id":"apchem-u8-c13","front":"water-ionization constant","back":"Kw = [H₃O⁺][OH⁻], equal to 1.0 × 10⁻¹⁴ at 25°C."},{"id":"apchem-u8-c14","front":"pH","back":"The negative base-10 logarithm of hydronium concentration."},{"id":"apchem-u8-c15","front":"pOH","back":"The negative base-10 logarithm of hydroxide concentration."},{"id":"apchem-u8-c16","front":"pKa","back":"The negative base-10 logarithm of Ka; a lower pKa indicates a stronger acid."},{"id":"apchem-u8-c17","front":"percent ionization","back":"The percentage of an initial weak acid or base that ionizes at equilibrium."},{"id":"apchem-u8-c18","front":"buffer","back":"A solution containing a weak acid-base conjugate pair that resists pH change."},{"id":"apchem-u8-c19","front":"buffer capacity","back":"The amount of added acid or base a buffer can absorb before its pH changes substantially."},{"id":"apchem-u8-c20","front":"Henderson-Hasselbalch equation","back":"An equation relating buffer pH to pKa and the conjugate-base-to-acid ratio."},{"id":"apchem-u8-c21","front":"acid-base indicator","back":"A weak acid or base whose conjugate forms have different colors over a pH range."},{"id":"apchem-u8-c22","front":"titration curve","back":"A graph of pH versus titrant volume showing buffer regions and equivalence points."},{"id":"apchem-u8-c23","front":"half-equivalence point","back":"The titration point where conjugate base and weak acid concentrations are equal, so pH = pKa."},{"id":"apchem-u8-c24","front":"polyprotic acid","back":"An acid capable of donating more than one proton in sequential equilibria."},{"id":"apchem-u8-eq1","front":"Water-ionization constant","back":"Use to relate hydronium and hydroxide concentrations at 25°C.","backImage":"./ap-chemistry-images/unit-8-formula-1.svg"},{"id":"apchem-u8-eq2","front":"pH","back":"Use to convert hydronium concentration to pH.","backImage":"./ap-chemistry-images/unit-8-formula-2.svg"},{"id":"apchem-u8-eq3","front":"pOH","back":"Use to convert hydroxide concentration to pOH.","backImage":"./ap-chemistry-images/unit-8-formula-3.svg"},{"id":"apchem-u8-eq4","front":"Acid-ionization constant","back":"Use for the equilibrium ionization of a weak acid HA.","backImage":"./ap-chemistry-images/unit-8-formula-4.svg"},{"id":"apchem-u8-eq5","front":"Conjugate-pair relationship","back":"Use to relate Ka and Kb for a conjugate acid-base pair at 25°C.","backImage":"./ap-chemistry-images/unit-8-formula-5.svg"},{"id":"apchem-u8-eq6","front":"Henderson-Hasselbalch equation","back":"Use to find a buffer's pH from pKa and the conjugate-base-to-acid ratio.","backImage":"./ap-chemistry-images/unit-8-formula-6.svg"},{"id":"apchem-u8-eq7","front":"pH-pOH relationship","back":"Use at 25°C to convert between pH and pOH.","backImage":"./ap-chemistry-images/unit-8-formula-7.svg"}],"questions":[],"feynmanPrompts":[{"id":"apchem-u8-f1","prompt":"Strong and weak acids and bases"},{"id":"apchem-u8-f2","prompt":"Buffers and the Henderson-Hasselbalch relationship"},{"id":"apchem-u8-f3","prompt":"Acid-base titration curves"}]},{"id":"apchem-unit-9","name":"AP Chemistry · Unit 9","shortName":"Unit 9: Thermodynamics and Electrochemistry","builtIn":true,"sourceTitle":"AP Chemistry Course and Exam Description, Effective Fall 2024","sourceUrl":"https://apcentral.collegeboard.org/media/pdf/ap-chemistry-course-and-exam-description.pdf","cards":[{"id":"apchem-u9-c1","front":"entropy","back":"A state function related to energy dispersal and the number of accessible microstates."},{"id":"apchem-u9-c2","front":"second law of thermodynamics","back":"A spontaneous process increases the total entropy of the universe."},{"id":"apchem-u9-c3","front":"Gibbs free energy","back":"A state function that predicts thermodynamic favorability at constant temperature and pressure."},{"id":"apchem-u9-c4","front":"thermodynamically favorable process","back":"A process with ΔG < 0 under the stated conditions."},{"id":"apchem-u9-c5","front":"standard free-energy change","back":"The Gibbs free-energy change when reactants and products are in their standard states."},{"id":"apchem-u9-c6","front":"equilibrium and free energy","back":"At equilibrium ΔG = 0, Q = K, and there is no net driving force."},{"id":"apchem-u9-c7","front":"galvanic cell","back":"An electrochemical cell that uses a thermodynamically favorable redox reaction to produce electrical energy."},{"id":"apchem-u9-c8","front":"electrolytic cell","back":"An electrochemical cell that uses external electrical energy to drive a nonspontaneous reaction."},{"id":"apchem-u9-c9","front":"anode","back":"The electrode where oxidation occurs."},{"id":"apchem-u9-c10","front":"cathode","back":"The electrode where reduction occurs."},{"id":"apchem-u9-c11","front":"salt bridge","back":"An ion-conducting connection that maintains electrical neutrality in electrochemical half-cells."},{"id":"apchem-u9-c12","front":"cell potential","back":"The electrical potential difference between a cell's cathode and anode."},{"id":"apchem-u9-c13","front":"standard reduction potential","back":"The potential for a reduction half-reaction under standard conditions relative to the standard hydrogen electrode."},{"id":"apchem-u9-c14","front":"standard hydrogen electrode","back":"The reference electrode assigned a standard reduction potential of 0.00 V."},{"id":"apchem-u9-c15","front":"Nernst equation","back":"An equation relating cell potential to standard potential, temperature, electron transfer, and reaction quotient."},{"id":"apchem-u9-c16","front":"Faraday's constant","back":"The magnitude of electric charge per mole of electrons, approximately 96,485 C mol⁻¹."},{"id":"apchem-u9-c17","front":"electrolysis","back":"Use of electrical energy to drive a nonspontaneous redox reaction."},{"id":"apchem-u9-c18","front":"electroplating","back":"Electrolytic deposition of a metal coating on an electrode."},{"id":"apchem-u9-c19","front":"charge stoichiometry","back":"Quantitative relation among current, time, charge, moles of electrons, and chemical amount in electrolysis."},{"id":"apchem-u9-c20","front":"concentration cell","back":"A galvanic cell whose potential arises from a concentration difference between otherwise similar half-cells."},{"id":"apchem-u9-eq1","front":"Gibbs free energy","back":"Use to combine enthalpy and entropy to predict favorability at a specified temperature.","backImage":"./ap-chemistry-images/unit-9-formula-1.svg"},{"id":"apchem-u9-eq2","front":"Free energy and equilibrium","back":"Use to connect the standard free-energy change to the equilibrium constant.","backImage":"./ap-chemistry-images/unit-9-formula-2.svg"},{"id":"apchem-u9-eq3","front":"Free energy and cell potential","back":"Use to connect electrochemical potential and reaction free energy.","backImage":"./ap-chemistry-images/unit-9-formula-3.svg"},{"id":"apchem-u9-eq4","front":"Standard cell potential","back":"Use standard reduction potentials to find the voltage of a galvanic cell.","backImage":"./ap-chemistry-images/unit-9-formula-4.svg"},{"id":"apchem-u9-eq5","front":"Nernst equation","back":"Use to find cell potential under nonstandard conditions.","backImage":"./ap-chemistry-images/unit-9-formula-5.svg"},{"id":"apchem-u9-eq6","front":"Electrical charge","back":"Use current and time to calculate charge transferred during electrolysis.","backImage":"./ap-chemistry-images/unit-9-formula-6.svg"},{"id":"apchem-u9-eq7","front":"Electrolysis amount","back":"Use Faraday's constant to convert charge to moles of electrons.","backImage":"./ap-chemistry-images/unit-9-formula-7.svg"}],"questions":[],"feynmanPrompts":[{"id":"apchem-u9-f1","prompt":"Entropy, enthalpy, and Gibbs free energy"},{"id":"apchem-u9-f2","prompt":"Galvanic and electrolytic cells"},{"id":"apchem-u9-f3","prompt":"Cell potential, the Nernst equation, and electrolysis"}]}];
